const items = $input.all();
let apis = [];

try {
  if (items.length > 0) {
    const firstItem = items[0].json;
    if (firstItem && firstItem.recordsets && firstItem.recordsets.length > 0) {
      apis = firstItem.recordsets[0];
    } else if (firstItem && firstItem.recordset) {
      apis = firstItem.recordset;
    } else {
      apis = items.map(item => item.json).filter(r => r && r.ApiCode);
    }
  }
} catch(e) {
  return [{ json: { api_list_text: '(Loi khi xu ly danh sach API: ' + e.message + ')' } }];
}

if (!apis || !apis.length) {
  return [{ json: { api_list_text: '(Khong lay duoc danh sach API tu he thong)' } }];
}

const grouped = {};
for (const api of apis) {
  const cat = api.Category || 'Khac';
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push('- ' + api.ApiCode + ' -> ' + (api.ApiDescription || api.ApiName) + ' [' + api.ExecutionType + ']');
}

let text = 'DANH SACH API HE THONG:\n';
for (const [cat, groupItems] of Object.entries(grouped)) {
  text += '\n===== ' + cat + ' =====\n' + groupItems.join('\n');
}

return [{ json: { api_list_text: text } }];

const items = $input.all();
const parseNode = $('Parse Input Co Ban').item.json;
const ApiCode = parseNode.ApiCode || '';

if (parseNode.need_confirm) {
   return [{ json: { ket_qua: "⚠️ Dữ liệu hợp lệ. Vui lòng kiểm tra kỹ và bấm **XÁC NHẬN** để hệ thống thực thi lệnh " + ApiCode, so_ban_ghi: 0, ApiCode, isConfirm_Review: true } }];
}

let payload = [];
try {
  if (items.length > 0) {
    const first = items[0].json;
    if (first && first.recordsets && first.recordsets[0]) {
      payload = first.recordsets[0];
    } else if (first && first.recordset) {
      payload = first.recordset;
    } else if (first && Array.isArray(first)) {
      payload = first;
    } else {
      payload = items.map(i => i.json).filter(r => r && !r.error);
    }
    if (first && first.error) {
      return [{ json: { ket_qua: 'Lỗi Database (' + ApiCode + '): ' + (first.message || JSON.stringify(first.error)), loi: true } }];
    }
  }
} catch(e) {}

if (!payload || payload.length === 0) {
  return [{ json: { ket_qua: 'Thực thi thành công nhưng hệ thống trả về rỗng.', so_ban_ghi: 0, ApiCode } }];
}

const keys = Object.keys(payload[0]).filter(k => !k.startsWith('_'));
const total = payload.length;
let text = 'Tìm thấy ' + total + ' kết quả:\n\n';
text += '| STT | ' + keys.join(' | ') + ' |\n';
text += '|---|' + keys.map(() => '---').join('|') + ' |\n';
text += payload.slice(0, 20).map((row, i) => {
  return '| ' + (i + 1) + ' | ' + keys.map(k => String(row[k] !== null && row[k] !== undefined ? row[k] : '').replace(/\|/g, '-')).join(' | ') + ' |';
}).join('\n');
if (total > 20) text += '\n\n... và ' + (total - 20) + ' kết quả khác chênh lệch.';

return [{ json: { ket_qua: text, so_ban_ghi: total, ApiCode } }];

const data = $input.item.json;
return [{ json: {
  ket_qua: data.message || 'Yeu cau khong hop le.',
  loi: true
}}];

const originalWebhook = $('Webhook Co Ban').item ? $('Webhook Co Ban').item : $('Webhook Nang Cao').item;
const rawWebhook = originalWebhook.json;
const body = rawWebhook.body || rawWebhook;
const headers = rawWebhook.headers || {};
const ApiCode = (body.ApiCode || '').trim();
const isConfirmParam = parseInt(body.isConfirm || '0', 10);

if (!ApiCode) return [{ json: { loi: true, hop_le: false, message: 'Thieu ApiCode' } }];

const dbItems = $input.all();
if (!dbItems || dbItems.length === 0 || !dbItems[0].json || dbItems[0].json.error) {
    return [{ json: { loi: true, hop_le: false, message: 'Metadata error: ' + (dbItems[0]?.json?.error?.message || '') } }];
}
let metadata = dbItems[0].json;
if (metadata.recordsets && metadata.recordsets[0] && metadata.recordsets[0][0]) {
  metadata = metadata.recordsets[0][0];
} else if (metadata.recordset && metadata.recordset[0]) {
  metadata = metadata.recordset[0];
}

if (!metadata || !metadata.StoredProcedure) {
    return [{ json: { loi: true, hop_le: false, message: 'API chưa được đăng ký trong hệ thống: ' + ApiCode } }];
}

const spName = metadata.StoredProcedure;
const isConfirmReq = metadata.IsConfirm === true || metadata.IsConfirm === 1;

let tokenStr = body.token || headers.authorization || headers.Authorization || headers.token || '';
if (tokenStr.startsWith('Bearer ')) tokenStr = tokenStr.split(' ')[1];

let realUsername = body.username || 'UNKNOWN';
let userRoles = ['USER'];
let isJwtParsed = false;
if (tokenStr && tokenStr !== 'Bearer empty' && tokenStr !== 'empty' && tokenStr !== 'null') {
    try {
      const parts = tokenStr.split('.');
      if (parts.length === 3) {
        const payload = JSON.parse(Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8'));
        let r = payload.role || payload.Role || payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || 'USER';
        userRoles = Array.isArray(r) ? r.map(x => String(x).toUpperCase()) : String(r).toUpperCase().split(',');
        realUsername = payload.UserName || payload.username || payload.sub || payload.unique_name || payload.name || payload.Name || realUsername;
        isJwtParsed = true;
      }
    } catch(e) {}
}

if (realUsername === 'Demo' || realUsername === 'UNKNOWN') {
    return [{ json: { loi: true, hop_le: false, message: 'Phiên đăng nhập không hợp lệ hoặc đã hết hạn.' } }];
}

// Chặn quyền
const MANAGER_APIS = ['@xem_doanh_so', '@import_trong_tam', '@de_xuat_khuyen_mai'];
if (MANAGER_APIS.includes(ApiCode)) {
   const isManager = userRoles.includes('ADMIN') || userRoles.includes('MANAGER') || userRoles.includes('CEO') || userRoles.includes('QUANLY');
   if (!isManager && isJwtParsed) {
      return [{ json: { loi: true, hop_le: false, message: '⛔ Từ chối truy cập: API yêu cầu quyền Quản Lý. Ban la ' + userRoles.join(',') } }];
   }
}

let params = {};
if (typeof body.params === 'string') {
  try { params = JSON.parse(body.params); } catch(e) {}
} else if (typeof body.params === 'object' && body.params !== null) {
  params = body.params;
}

function esc(val) {
  if (val === undefined || val === null || String(val).trim() === '') return 'NULL';
  let str = typeof val === 'object' ? JSON.stringify(val) : String(val);
  return "N'" + str.replace(/'/g, "''") + "'";
}

let sqlArgs = Object.keys(params).map(k => `${k}=${esc(params[k])}`);
sqlArgs.unshift(`@Username=${esc(realUsername)}`);
let sql = `EXEC ${spName} ${sqlArgs.join(', ')};`;

if (isConfirmReq && isConfirmParam === 0) {
    return [{ json: { hop_le: true, need_confirm: true, ApiCode, sql_query: null } }];
}

return [{ json: { hop_le: true, need_confirm: false, ApiCode, sql_query: sql } }];
